import React, { useMemo, useState } from 'react';
import { Trash2, ExternalLink, Check, Tag, Eye, Info } from 'lucide-react';
import { useApp } from '../../context/AppContext';
import { FullPage } from '../common';
import { Field, Switch, ErrorBox, Spinner } from '../../ui/ui';
import ImagesField from './ImagesField';
import { rowToProduct } from '../../data/siteContent';

const IMG_COLS = ['תמונה1', 'תמונה2', 'תמונה3', 'תמונה4'];
const csvList = (s) => String(s || '').split(',').map(x => x.trim()).filter(Boolean);

/**
 * עריכת מוצר (גם עבודות גרפיקה). row = השורה מהגיליון, או null למוצר חדש.
 */
export default function ProductEditor({ sheet, row, cats, defaultCat, onClose, onSaved }) {
  const { ops, settings, raw, t } = useApp();
  const isNew = !row;
  const emojiCol = Object.keys(row || raw[sheet]?.[0] || {}).find(k => k.includes('אמוג')) || "אמוג'י";
  const [f, setF] = useState(() => ({
    'שם': row?.['שם'] || '', 'מחיר': row?.['מחיר'] || '', 'כמות_במלאי': row?.['כמות_במלאי'] ?? '',
    'קטגוריה': row?.['קטגוריה'] ?? defaultCat ?? '', 'תיאור': row?.['תיאור'] || '', 'הערת מחיר': row?.['הערת מחיר'] || '',
    [emojiCol]: row?.[emojiCol] || '',
    'מבצע_כמות': row?.['מבצע_כמות'] || '', 'מבצע_מחיר': row?.['מבצע_מחיר'] || '', 'תיאור_מבצע': row?.['תיאור_מבצע'] || '',
    'שם_מבצע': row?.['שם_מבצע'] || '', 'סוג_מבצע': row?.['סוג_מבצע'] || '',
    'מוצג': row?.['מוצג'] || '',
  }));
  const [images, setImages] = useState(() => IMG_COLS.map(c => row?.[c] || '').filter(Boolean));
  const id = row?.['מזהה'];

  // מוצרים נבחרים: אם הרשימה ריקה האתר מציג את 8 הראשונים
  const visibleIds = useMemo(() => (raw[sheet] || []).filter(r => r['שם']).map(rowToProduct).filter(p => !p.hidden).map(p => p.id), [raw, sheet]);
  const featuredList = csvList(settings.featured_ids);
  const featuredNow = id ? (featuredList.length ? featuredList.includes(id) : visibleIds.slice(0, 8).includes(id)) : false;
  const [featured, setFeatured] = useState(featuredNow);
  const cheapMax = Number(t('home.under100_max')) || 100;
  const excluded = csvList(settings.under100_exclude);
  const [cheap, setCheap] = useState(id ? !excluded.includes(id) : true);

  const [deal, setDeal] = useState(!!(f['מבצע_כמות'] || f['מבצע_מחיר']));
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState(null);
  const set = (k) => (e) => setF(x => ({ ...x, [k]: e.target.value }));
  const price = Number(f['מחיר']) || 0;
  const stock = String(f['כמות_במלאי']).trim();

  const save = async () => {
    if (!f['שם'].trim()) { setErr('צריך לתת שם למוצר'); return; }
    if (f['מחיר'] && isNaN(Number(f['מחיר']))) { setErr('המחיר צריך להיות מספר'); return; }
    if (stock && isNaN(Number(stock))) { setErr('המלאי צריך להיות מספר (או ריק = ללא הגבלה)'); return; }
    if (deal && (!Number(f['מבצע_כמות']) || !Number(f['מבצע_מחיר']))) { setErr('במבצע צריך למלא כמות ומחיר (או לכבות את המבצע)'); return; }
    setBusy(true); setErr(null);
    try {
      const out = { ...f, 'שם': f['שם'].trim() };
      if (!deal) ['מבצע_כמות', 'מבצע_מחיר', 'תיאור_מבצע', 'שם_מבצע', 'סוג_מבצע'].forEach(k => { out[k] = ''; });
      IMG_COLS.forEach((c, i) => { out[c] = images[i] || ''; });
      if (id) out['מזהה'] = id;
      const newId = await ops.saveRow(sheet, out);
      const pid = String(newId || id);
      // נבחרים / עד 100 – נשמרים בהגדרות
      if (sheet === 'products') {
        const extra = {};
        if (featured !== featuredNow || (isNew && featured)) {
          const base = featuredList.length ? featuredList : visibleIds.slice(0, 8);
          extra.featured_ids = (featured ? [...new Set([...base, pid])] : base.filter(x => x !== pid)).join(',');
        }
        const wasCheap = !excluded.includes(pid);
        if (cheap !== wasCheap) extra.under100_exclude = (cheap ? excluded.filter(x => x !== pid) : [...excluded, pid]).join(',');
        if (Object.keys(extra).length) await ops.saveSettings(extra);
      }
      onSaved?.(isNew ? 'המוצר נוסף ✓' : 'המוצר נשמר ✓');
      onClose();
    } catch (e) { setErr(e.message); setBusy(false); }
  };
  const del = async () => {
    if (!window.confirm(`למחוק את "${row['שם']}"? אי אפשר לבטל.\n(אפשר במקום זה להסתיר אותו מהאתר)`)) return;
    setBusy(true);
    try { await ops.deleteRow(sheet, id); onSaved?.('המוצר נמחק'); onClose(); } catch (e) { setErr(e.message); setBusy(false); }
  };

  return (
    <FullPage title={isNew ? (sheet === 'graphics' ? 'עבודה חדשה' : 'מוצר חדש') : 'עריכת מוצר'} onBack={onClose}
      extra={id && <button className="a-btn ghost sm" onClick={() => window.open(`/product/${encodeURIComponent(id)}`, '_blank')}><ExternalLink size={14} /> באתר</button>}
      footer={<>
        {!isNew && <button className="a-btn danger-ghost icon" onClick={del} disabled={busy} aria-label="מחיקה"><Trash2 size={18} /></button>}
        <button className="a-btn primary wide" onClick={save} disabled={busy}>{busy ? <Spinner /> : <><Check size={18} /> שמירה לגוגל שיטס</>}</button>
      </>}>
      <span className="a-label">תמונות <small className="muted" style={{ fontWeight: 400 }}>· הראשונה היא התמונה הראשית</small></span>
      <ImagesField images={images} onChange={setImages} emoji={f[emojiCol] || '🎁'} />

      <Field label="שם המוצר" required><input className="a-input" value={f['שם']} onChange={set('שם')} autoFocus={isNew} /></Field>
      <div className="a-row">
        <Field label="מחיר ₪" hint={!price ? 'ריק = "מחיר לפי הצעה"' : null}><input className="a-input" inputMode="decimal" value={f['מחיר']} onChange={set('מחיר')} /></Field>
        <Field label="כמה במלאי" hint={stock === '' ? 'ריק = ללא הגבלה' : Number(stock) <= 0 ? 'יוצג "אזל מהמלאי"' : null}>
          <input className="a-input" inputMode="numeric" value={f['כמות_במלאי']} onChange={set('כמות_במלאי')} placeholder="∞" />
        </Field>
      </div>
      {!price && <Field label="מה לכתוב במקום מחיר"><input className="a-input" value={f['הערת מחיר']} onChange={set('הערת מחיר')} placeholder={t('product.price_note')} /></Field>}
      <Field label="קטגוריה">
        <select className="a-select" value={f['קטגוריה']} onChange={set('קטגוריה')}>
          <option value="">— בלי קטגוריה (לא יוצג בקטגוריות) —</option>
          {cats.map(c => <option key={c.id} value={c.id}>{c.label}</option>)}
          {f['קטגוריה'] && !cats.some(c => c.id === f['קטגוריה']) && <option value={f['קטגוריה']}>{f['קטגוריה']} (לא קיימת)</option>}
        </select>
      </Field>
      <Field label="תיאור"><textarea className="a-textarea" rows={4} value={f['תיאור']} onChange={set('תיאור')} /></Field>
      <Field label="אימוג׳י (מוצג כשאין תמונה)"><input className="a-input" value={f[emojiCol]} onChange={set(emojiCol)} placeholder="🎁" style={{ maxWidth: 120 }} /></Field>

      <div className="box">
        <h4><Eye size={16} /> איפה המוצר מופיע</h4>
        <div className="tg"><span>מוצג באתר<small>כבוי = מוסתר מהגולשים, נשאר בגיליון</small></span><Switch checked={f['מוצג'] !== 'לא'} onChange={(v) => setF(x => ({ ...x, 'מוצג': v ? '' : 'לא' }))} /></div>
        {sheet === 'products' && <>
          <div className="tg"><span>במוצרים הנבחרים בדף הבית</span><Switch checked={featured} onChange={setFeatured} /></div>
          <div className="tg"><span>במתנות עד {cheapMax} ₪{price > cheapMax || !price ? <small>רק למוצרים במחיר עד {cheapMax} ₪</small> : null}</span>
            <Switch checked={cheap && price > 0 && price <= cheapMax} disabled={!price || price > cheapMax} onChange={setCheap} /></div>
        </>}
      </div>

      <div className="box">
        <div className="tg" style={{ paddingTop: 0 }}><h4 style={{ margin: 0 }}><Tag size={16} /> מבצע</h4><Switch checked={deal} onChange={setDeal} /></div>
        {deal && <>
          <div className="a-row" style={{ marginTop: 10 }}>
            <Field label="כמות"><input className="a-input" inputMode="numeric" value={f['מבצע_כמות']} onChange={set('מבצע_כמות')} placeholder="2" /></Field>
            <Field label="במחיר ₪"><input className="a-input" inputMode="decimal" value={f['מבצע_מחיר']} onChange={set('מבצע_מחיר')} placeholder="200" /></Field>
          </div>
          {Number(f['מבצע_כמות']) > 0 && Number(f['מבצע_מחיר']) > 0 && <p className="a-alert ok" style={{ marginTop: 0 }}>{f['מבצע_כמות']} יחידות ב־₪{f['מבצע_מחיר']}{price ? ` (במקום ₪${Number(f['מבצע_כמות']) * price})` : ''}</p>}
          <Field label="מה כתוב על התגית" hint='למשל "2 ב־200". ריק = "מבצע!"'><input className="a-input" value={f['תיאור_מבצע']} onChange={set('תיאור_מבצע')} /></Field>
          <Field label="שם קבוצת מבצע (לא חובה)" hint="מוצרים עם אותו שם קבוצה נספרים יחד. למשל: ראנר + ראנר אחר = 2 ב־200."><input className="a-input" value={f['שם_מבצע']} onChange={set('שם_מבצע')} /></Field>
          <Field label="סוג במבצע משולב (לא חובה)" hint='למבצע "אחד מכל סוג" – למשל "ראנר" ו"כיסוי חלה" באותה קבוצה. ההנחה חלה רק כשיש בסל מכל סוג.'><input className="a-input" value={f['סוג_מבצע']} onChange={set('סוג_מבצע')} /></Field>
        </>}
      </div>
      {isNew && <p className="a-hint"><Info size={13} style={{ verticalAlign: -2 }} /> המוצר יתווסף בסוף הלשונית "{sheet === 'graphics' ? 'גרפיקה' : 'מוצרים'}" בגיליון.</p>}
      <ErrorBox message={err} />
    </FullPage>
  );
}
